-- Load ALL 665 facts into knowledge_facts
-- Run this AFTER combined_migration.sql (so the table exists)

-- Enable pg_trgm for fuzzy text search
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Clear existing data
DELETE FROM knowledge_facts;

-- Insert all 665 facts

-- Add GIN index for trigram similarity search
CREATE INDEX IF NOT EXISTS idx_knowledge_facts_trgm ON knowledge_facts USING GIN (fact_text gin_trgm_ops);

-- Add index on category
CREATE INDEX IF NOT EXISTS idx_knowledge_facts_category ON knowledge_facts (category);

-- Analyze for query planner
ANALYZE knowledge_facts;
